import json, csv
try:
    json.loads('{"username": "Kakade",}')
except json.JSONDecodeError as e:
    print(f"Invalid JSON line {e.lineno}: {e.msg}")
count = 0
with open("kakade.csv", newline="", encoding="utf-8") as f:
    for row in csv.DictReader(f):
        if row.get("name") == "Kakade":
            count += 1
print(count)
